$appB64 = ""
$srvB64 = ""
$appPath = "D:\CasinoControl\frontend\src\App.jsx"
$srvPath = "D:\CasinoControl\backend\server.js"
Get-Process node -ErrorAction SilentlyContinue | Stop-Process -Force
Get-Process electron -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Sleep -Seconds 1
[IO.File]::WriteAllBytes($appPath, [Convert]::FromBase64String($appB64))
[IO.File]::WriteAllBytes($srvPath, [Convert]::FromBase64String($srvB64))
Write-Host "OK App $((Get-Item $appPath).Length) bytes Server $((Get-Item $srvPath).Length) bytes - FECHA + BORRAR FIX" -ForegroundColor Green
Set-Location "D:\CasinoControl\frontend"
npm run build | Out-Null
Write-Host "Listo. Inicia backend: cd D:\CasinoControl\backend ; node server.js"
Write-Host "Y luego: cd D:\CasinoControl\frontend ; npx electron ."
